// ─── File: CacheLayersDemo.java ───
// CDN (static at edge) vs Redis (dynamic near app) vs Semantic cache (match by meaning).
import java.util.*;
import java.util.logging.*;

public class CacheLayersDemo {
    private static final Logger log = Logger.getLogger("LAYERS");
    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setFormatter(new BankLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.ALL);
    }

    public static void main(String[] args) {
        RequestRouter router = new RequestRouter(
            new CdnEdge(), new RedisCache(), new SemanticCache(0.85));

        // CDN: static content served from the nearest edge (beats geographic distance).
        log.info("=== CDN: static content at the edge (close to the USER) ===");
        log.info(() -> router.handleStatic("/assets/logo.png", "chennai"));

        // Redis: dynamic data served near the application (beats DB latency).
        log.info("=== Redis: dynamic data near the APPLICATION ===");
        log.info(() -> router.handleDynamic("balance:SAV2001"));
        log.info(() -> router.handleDynamic("balance:SAV2001"));   // 2nd read = Redis hit

        // Semantic cache: paraphrased LLM questions reuse a cached answer (match by MEANING).
        log.info("=== Semantic cache: match by embedding similarity, not exact key ===");
        log.info(() -> router.handleQuestion("What is the penalty for closing my fixed deposit early?"));
        log.info(() -> router.handleQuestion("How much do I lose if I break my FD before maturity?"));
    }
}

// ─── edge/CdnEdge.java (static content at the edge) ───
class CdnEdge {
    private static final Logger log = Logger.getLogger("LAYERS");
    private final Map<String, String> edgeCache = new HashMap<>();
    String serve(String path, String edge) {
        String key = edge + ":" + path;
        if (edgeCache.containsKey(key)) return "served " + path + " from EDGE(" + edge + ") [hit]";
        edgeCache.put(key, "content");   // fetched from origin once, cached at this edge
        log.fine(() -> "origin fetch for " + path + " → cached at " + edge);
        return "served " + path + " from EDGE(" + edge + ") [filled from origin]";
    }
}

// ─── cache/RedisCache.java (dynamic data near the app) ───
class RedisCache {
    private final Map<String, String> store = new HashMap<>();
    private final Map<String, String> db = new HashMap<>(Map.of(
        "balance:SAV2001", "1000000", "balance:CUR3001", "250000"));
    String get(String key) {
        String v = store.get(key);
        if (v != null) return "Redis HIT " + key + "=" + v;
        v = db.get(key);                 // slow DB on miss (cache-aside)
        store.put(key, v);
        return "Redis MISS→DB " + key + "=" + v + " (cached)";
    }
}

// ─── semantic/SemanticCache.java (embedding similarity match) ───
class SemanticCache {
    private static final Logger log = Logger.getLogger("LAYERS");
    private final double threshold;
    private final List<double[]> embeddings = new ArrayList<>();
    private final List<String> answers = new ArrayList<>();
    SemanticCache(double threshold) { this.threshold = threshold; }

    String ask(String question) {
        double[] q = embed(question);
        // Find the most similar cached question (cosine similarity).
        double best = -1; int bestIdx = -1;
        for (int i = 0; i < embeddings.size(); i++) {
            double sim = cosine(q, embeddings.get(i));
            if (sim > best) { best = sim; bestIdx = i; }
        }
        if (bestIdx >= 0 && best >= threshold) {
            final double b = best;
            log.fine(() -> "semantic HIT sim=" + String.format("%.2f", b));
            return "CACHE HIT (sim=" + String.format("%.2f", best) + "): " + answers.get(bestIdx);
        }
        // Miss → call the expensive model, then cache the answer + embedding.
        String answer = callModel(question);
        embeddings.add(q); answers.add(answer);
        return "MODEL CALL (cached now): " + answer;
    }
    private String callModel(String q) {
        return "Breaking an FD early typically incurs a 1% rate penalty on the deposit.";
    }
    // Toy embedding: bag-of-keywords vector (a real system uses an embedding model).
    private double[] embed(String text) {
        String[] kw = {"penalty","close","fixed","deposit","early","lose","break","fd","maturity"};
        String t = text.toLowerCase();
        double[] v = new double[kw.length];
        for (int i = 0; i < kw.length; i++) v[i] = t.contains(kw[i]) ? 1.0 : 0.0;
        return v;
    }
    private double cosine(double[] a, double[] b) {
        double dot = 0, na = 0, nb = 0;
        for (int i = 0; i < a.length; i++) { dot += a[i]*b[i]; na += a[i]*a[i]; nb += b[i]*b[i]; }
        return (na == 0 || nb == 0) ? 0 : dot / (Math.sqrt(na) * Math.sqrt(nb));
    }
}

// ─── router/RequestRouter.java ───
class RequestRouter {
    private final CdnEdge cdn; private final RedisCache redis; private final SemanticCache semantic;
    RequestRouter(CdnEdge cdn, RedisCache redis, SemanticCache semantic) {
        this.cdn = cdn; this.redis = redis; this.semantic = semantic;
    }
    String handleStatic(String path, String edge) { return cdn.serve(path, edge); }
    String handleDynamic(String key) { return redis.get(key); }
    String handleQuestion(String question) { return semantic.ask(question); }
}

